package com.gymflow.category; import com.gymflow.gym.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class CategoryService{private final CategoryRepository categories;private final GymRepository gyms;public CategoryService(CategoryRepository c,GymRepository g){categories=c;gyms=g;}@Transactional public CategoryResponse create(UUID gymId,CategoryRequest r){Gym gym=gyms.findById(gymId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Gimnasio no encontrado."));if(categories.existsByGym_IdAndNameIgnoreCase(gymId,r.name().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Ya existe esa categoría.");return CategoryResponse.from(categories.save(new Category(gym,r.name().trim(),r.description())));}@Transactional(readOnly=true)public List<CategoryResponse> findAll(UUID gymId){return categories.findAllByGym_IdOrderByName(gymId).stream().map(CategoryResponse::from).toList();}}
